import{_ as t,o as e,c as a,ab as r}from"./chunks/framework.DCf1Sbhf.js";const s="/hubHooks/assets/img_1.TMFny2WT.png",d=JSON.parse('{"title":"Memory概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/langChain/memory.md","filePath":"ai/langChain/memory.md","lastUpdated":1773192027000}'),i={name:"ai/langChain/memory.md"};function m(l,o,n,_,p,c){return e(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="memory概述" tabindex="-1">Memory概述 <a class="header-anchor" href="#memory概述" aria-label="Permalink to &quot;Memory概述&quot;">​</a></h1><p><strong>Memory，是LangChain中用于多轮对话中保存和管理上下文信息（比如文本、图像、音频等）的组 件。</strong> 它让应用能够记住用户之前说了什么，从而实现对话的 <strong>上下文感知能力</strong> ，为构建真正智能和上下文 感知的链式对话系统提供了基础。</p><p><img src="'+s+'" alt="Memory设计理念"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li>输入问题：({&quot;question&quot;: ...})</li><li>读取历史消息：从Memory中READ历史消息（{&quot;past_messages&quot;: [...]}）</li><li>构建提示（Prompt)：读取到的历史消息和当前问题会被合并，构建一个新的Prompt</li><li>模型处理：构建好的提示会被传递给语言模型进行处理。语言模型根据提示生成一个输出。</li><li>解析输出：输出解析器通过正则表达式 regex(&quot;Answer: (.*)&quot;)来解析，返回一个回答（{&quot;answer&quot;: ...}）给用户</li><li>得到回复并写入Memory：新生成的回答会与当前的问题一起写入Memory，更新对话历史。 Memory会存储最新的对话内容，为后续的对话提供上下文支持。</li></ol></div>',4)])])}const y=t(i,[["render",m]]);export{d as __pageData,y as default};
